const { Client } = require('pg');

async function main() {
  const client = new Client({ connectionString: 'postgresql://postgres:postgres@localhost:5432/postgres' });
  await client.connect();
  await client.query('CREATE TABLE IF NOT EXISTS greetings (id serial PRIMARY KEY, message text NOT NULL)');
  await client.query('INSERT INTO greetings (message) VALUES ($1)', ['Hallo, Welt!']);
  const res = await client.query('SELECT message FROM greetings LIMIT 1');
  console.log(res.rows[0]);
  await client.end();
}

main().catch(console.error);
